urlset:
{#- Zola lists the undated _draft.md templates here even though it never renders them. Redirects are not pages to index. #}
{%- for sitemap_entry in entries %}
{%- if sitemap_entry.permalink is not ending_with(pat="/draft/") and not sitemap_entry.extra.redirect_to %}

    {{ sitemap_entry.permalink | escape_xml | safe }}
    {%- if sitemap_entry.updated %}
    {{ sitemap_entry.updated }}
    {%- endif %}

{%- endif %}
{%- endfor %}
